// Arma un aviso legible de que se rompio y donde.
const e = $input.first().json || {};
const wf  = (e.workflow && e.workflow.name) || 'workflow desconocido';
const exe = e.execution || {};
const err = exe.error || {};

const lineas = [
  'SE ROMPIO UNA AUTOMATIZACION DE GONVRA',
  '',
  `Automatizacion: ${wf}`,
  `Nodo que fallo: ${exe.lastNodeExecuted || '?'}`,
  `Error: ${(err.message || 'sin mensaje').slice(0, 300)}`,
  `Cuando: ${new Date().toLocaleString('es-AR')}`,
  ''
];

if (exe.url) lineas.push(`Ver detalle: ${exe.url}`);
lineas.push('');
lineas.push('Si es un error de red, suele arreglarse solo en el proximo intento.');
lineas.push('Si se repite, anotalo en BITACORA-ERRORES.md');

return [{ json: { texto: lineas.join('\n') } }];
